function weaponForSlot(slot=state.weaponIndex){return weaponData.find(weapon=>weapon.id===classLoadout.slots[slot])||weaponData[1];}
function ammoForWeapon(weapon=weaponForSlot()){return state.ammo[weaponData.findIndex(item=>item.id===weapon.id)];}
function hasAttachment(weaponId,attachmentId){return(classLoadout.attachments[weaponId]||[]).includes(attachmentId);}
function isCamoUnlocked(id){return !['diamond','darkmatter'].includes(id)||progression.claimed.includes(id);}
function isSkinUnlocked(index){return index<5||progression.unlockedSkins.includes(index);}
function weaponCamoColor(weapon){return camoOptions.find(option=>option.id===classLoadout.camos[weapon.id]&&isCamoUnlocked(option.id))?.color??weapon.color;}
function weaponUnlocked(weapon){return state.level>=weapon.unlockLevel||classLoadout.slots.includes(weapon.id);}
function magazineCapacity(weapon){return weapon.mag+(hasAttachment(weapon.id,'extended')?Math.max(2,Math.ceil(weapon.mag*.3)):0);}
function saveClassLoadout(){localStorage.setItem('fl_class_loadout',JSON.stringify(classLoadout));}
function saveProgression(){localStorage.setItem('fl_progression',JSON.stringify(progression));updateProgressionButton();renderProgressionPanel();}
function updateProgressionButton(){const button=$('blackPassBtn');if(button)button.textContent=`BLACK PASS · ${progression.blackCoins} BC`;const balance=$('blackCoinBalance');if(balance)balance.textContent=`${progression.blackCoins} BLACK COINS`;}
function advanceChallenge(id,amount=1){ensureDailyChallenges();const challenge=dailyChallengeDefinitions.find(item=>item.id===id);if(!challenge||progression.daily.completed.includes(id))return;const current=Math.max(0,Number(progression.daily.progress[id])||0);progression.daily.progress[id]=Math.min(challenge.target,current+amount);if(progression.daily.progress[id]>=challenge.target){progression.daily.completed.push(id);progression.blackCoins+=challenge.reward;showToast(`CHALLENGE COMPLETE · +${challenge.reward} BLACK COINS`);}saveProgression();}
function claimPassReward(id){const reward=passRewards.find(item=>item.id===id);if(!reward||progression.claimed.includes(id))return;if(state.level<reward.level){showToast(`REQUIRES LEVEL ${reward.level}`);return;}if(progression.blackCoins<reward.cost){showToast('NOT ENOUGH BLACK COINS');return;}progression.blackCoins-=reward.cost;progression.claimed.push(id);if(reward.type==='skin')progression.unlockedSkins.push(reward.skin);saveProgression();refreshClassEditorLocks();showToast(`${reward.title} UNLOCKED`);}
function ensureDailyChallenges(){const today=new Date().toISOString().slice(0,10);if(progression.daily.date!==today)progression.daily={date:today,progress:{},completed:[]};}
function refreshClassEditorLocks(){document.querySelectorAll('#classSlots select').forEach(select=>{for(const option of select.options){const weapon=weaponData.find(item=>item.id===option.value);if(!weapon)continue;const locked=state.level<weapon.unlockLevel;option.disabled=locked;option.textContent=locked?`${weapon.name} · LEVEL ${weapon.unlockLevel}`:weapon.name;}});document.querySelectorAll('.camoSwatch').forEach(swatch=>{const camo=camoOptions.find(item=>item.name===swatch.getAttribute('aria-label'));if(camo){swatch.disabled=!isCamoUnlocked(camo.id);swatch.title=swatch.disabled?`${camo.name} · BLACK PASS REWARD`:camo.name;}});const skinSelect=$('operatorSkinSelect');if(skinSelect)for(const option of skinSelect.options){const index=Number(option.value);option.disabled=!isSkinUnlocked(index);option.textContent=isSkinUnlocked(index)?skins[index].name:`${skins[index].name} · BLACK PASS REWARD`;}}
function installOperatorPicker(){const card=document.querySelector('#classEditor .classEditorCard'),slots=$('classSlots');if(!card||!slots)return;const label=document.createElement('label');label.className='classSlot';label.textContent='OPERATOR SKIN';const select=document.createElement('select');select.id='operatorSkinSelect';select.setAttribute('aria-label','Operator skin');for(let index=0;index<skins.length;index++){const option=document.createElement('option');option.value=String(index);option.textContent=skins[index].name;option.disabled=!isSkinUnlocked(index);select.append(option);}select.value=String(classLoadout.skin);select.addEventListener('change',()=>{const skin=Number(select.value);if(!isSkinUnlocked(skin)){select.value=String(classLoadout.skin);return;}classLoadout.skin=skin;state.skinIndex=skin;saveClassLoadout();buildViewWeapon();});label.append(select);card.insertBefore(label,slots);refreshClassEditorLocks();}
let progressionTab='daily';
function renderProgressionPanel(){const panel=$('progressionPanel'),content=$('progressionContent');if(!panel||!content||!panel.classList.contains('open'))return;ensureDailyChallenges();updateProgressionButton();content.replaceChildren();if(progressionTab==='daily'){for(const challenge of dailyChallengeDefinitions){const card=document.createElement('section');card.className='challengeCard';const heading=document.createElement('h3');heading.textContent=challenge.title;const description=document.createElement('p');description.textContent=challenge.description;const progress=Math.min(challenge.target,Number(progression.daily.progress[challenge.id])||0);const meter=document.createElement('div');meter.className='challengeMeter';const fill=document.createElement('i');fill.style.width=`${progress/challenge.target*100}%`;meter.append(fill);const details=document.createElement('div');details.className='challengeDetails';details.textContent=progression.daily.completed.includes(challenge.id)?`COMPLETE · +${challenge.reward} BLACK COINS`:`${progress} / ${challenge.target} · ${challenge.reward} BLACK COINS`;card.append(heading,description,meter,details);content.append(card);}}else{for(const reward of passRewards){const card=document.createElement('section');card.className='passReward';const heading=document.createElement('h3');heading.textContent=reward.title;const info=document.createElement('p');info.textContent=`LEVEL ${reward.level} · ${reward.cost} BLACK COINS`;const button=document.createElement('button');button.className='secondaryBtn';const claimed=progression.claimed.includes(reward.id);button.textContent=claimed?'UNLOCKED':state.level<reward.level?`REACH LEVEL ${reward.level}`:`UNLOCK · ${reward.cost} BC`;button.disabled=claimed||state.level<reward.level||progression.blackCoins<reward.cost;button.addEventListener('click',()=>claimPassReward(reward.id));card.append(heading,info,button);content.append(card);}}}
function installProgressionMenu(){const button=document.createElement('button');button.id='blackPassBtn';button.className='secondaryBtn';document.querySelector('.menuButtons').append(button);const pauseButton=document.createElement('button');pauseButton.id='pauseBlackPassBtn';pauseButton.className='secondaryBtn';pauseButton.textContent='BLACK PASS';document.querySelector('.pauseActions').append(pauseButton);const panel=document.createElement('div');panel.id='progressionPanel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','progressionTitle');panel.innerHTML='<div class="progressionCard"><button id="progressionClose" class="settingsClose" aria-label="Close Black Pass">×</button><div class="eyebrow">FRONTLINE // DAILY OPERATIONS</div><div class="progressionHeader"><h2 id="progressionTitle">BLACK PASS</h2><b id="blackCoinBalance"></b></div><div class="progressionTabs"><button class="progressionTab active" data-view="daily">DAILY CHALLENGES</button><button class="progressionTab" data-view="pass">REWARD TRACK</button></div><div id="progressionContent"></div></div>';document.body.append(panel);const open=view=>{progressionTab=view;panel.classList.add('open');document.querySelectorAll('.progressionTab').forEach(tab=>tab.classList.toggle('active',tab.dataset.view===view));renderProgressionPanel();};button.addEventListener('click',()=>open('daily'));pauseButton.addEventListener('click',()=>open('daily'));$('progressionClose').addEventListener('click',()=>panel.classList.remove('open'));panel.addEventListener('pointerdown',event=>{if(event.target===panel)panel.classList.remove('open');});panel.querySelectorAll('.progressionTab').forEach(tab=>tab.addEventListener('click',()=>open(tab.dataset.view)));updateProgressionButton();}
function installClassEditor(){
  const button=document.createElement('button');button.id='classEditorBtn';button.className='secondaryBtn';button.textContent='CLASS CREATION';document.querySelector('.menuButtons').append(button);
  const panel=document.createElement('div');panel.id='classEditor';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','classEditorTitle');panel.innerHTML='<div class="classEditorCard"><button id="classEditorClose" class="settingsClose" aria-label="Close class creation">×</button><div class="eyebrow">OPERATOR LOADOUT</div><h2 id="classEditorTitle">CLASS CREATION</h2><p class="classEditorIntro">Choose two weapons, then fit or remove attachments and finishes.</p><div id="classSlots"></div><div id="weaponCustomization"></div></div>';document.body.append(panel);
  const close=()=>panel.classList.remove('open');button.addEventListener('click',()=>panel.classList.add('open'));panel.querySelector('#classEditorClose').addEventListener('click',close);panel.addEventListener('pointerdown',event=>{if(event.target===panel)close();});
  const render=()=>{const slots=panel.querySelector('#classSlots');slots.replaceChildren();for(let index=0;index<2;index++){const label=document.createElement('label');label.className='classSlot';label.textContent=`WEAPON SLOT ${index+1}`;const select=document.createElement('select');select.setAttribute('aria-label',`Weapon slot ${index+1}`);for(const weapon of weaponData){const option=document.createElement('option');option.value=weapon.id;option.textContent=weapon.name;select.append(option);}select.value=classLoadout.slots[index];select.addEventListener('change',()=>{if(select.value===classLoadout.slots[1-index]){select.value=classLoadout.slots[index];showToast('CHOOSE TWO DIFFERENT WEAPONS');return;}classLoadout.slots[index]=select.value;saveClassLoadout();render();if(state.playing){buildViewWeapon();updateHud();}});label.append(select);slots.append(label);}
    const customization=panel.querySelector('#weaponCustomization');customization.replaceChildren();for(let index=0;index<2;index++){const weapon=weaponData.find(item=>item.id===classLoadout.slots[index]);const section=document.createElement('section');section.className='weaponCustomization';const heading=document.createElement('h3');heading.textContent=`SLOT ${index+1} · ${weapon.name}`;section.append(heading);const attachmentRow=document.createElement('div');attachmentRow.className='attachmentOptions';for(const attachment of attachmentOptions){const label=document.createElement('label');label.className='attachmentOption';const input=document.createElement('input');input.type='checkbox';input.checked=hasAttachment(weapon.id,attachment.id);input.addEventListener('change',()=>{const selected=classLoadout.attachments[weapon.id]||[];classLoadout.attachments[weapon.id]=input.checked?[...new Set([...selected,attachment.id])]:selected.filter(id=>id!==attachment.id);saveClassLoadout();if(state.playing&&weaponForSlot().id===weapon.id)buildViewWeapon();});const text=document.createElement('span');text.textContent=attachment.name;label.append(input,text);attachmentRow.append(label);}section.append(attachmentRow);const camoLabel=document.createElement('div');camoLabel.className='camoLabel';camoLabel.textContent='CAMO';section.append(camoLabel);const swatches=document.createElement('div');swatches.className='camoSwatches';for(const camo of camoOptions){const swatch=document.createElement('button');swatch.type='button';swatch.className='camoSwatch';swatch.setAttribute('aria-label',camo.name);swatch.title=camo.name;swatch.style.background=camo.color===null?'linear-gradient(135deg,#202725 0 50%,#69745f 50%)':`#${camo.color.toString(16).padStart(6,'0')}`;swatch.classList.toggle('active',(classLoadout.camos[weapon.id]||'standard')===camo.id);swatch.addEventListener('click',()=>{classLoadout.camos[weapon.id]=camo.id;saveClassLoadout();render();if(state.playing&&weaponForSlot().id===weapon.id)buildViewWeapon();});swatches.append(swatch);}section.append(swatches);customization.append(section);}};
  render();
}

