function getAudioContext(){const AudioEngine=window.AudioContext||window.webkitAudioContext;if(!AudioEngine)return null;if(!audioContext){audioContext=new AudioEngine();soundBus=audioContext.createGain();soundBus.gain.value=soundVolume;soundBus.connect(audioContext.destination);}if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});return audioContext;}
function playTone(startHz,endHz,duration,wave='triangle',volume=.15,delay=0){const ctx=getAudioContext();if(!ctx||soundVolume<=0)return;const oscillator=ctx.createOscillator(),gain=ctx.createGain(),start=ctx.currentTime+delay;oscillator.type=wave;oscillator.frequency.setValueAtTime(startHz,start);oscillator.frequency.exponentialRampToValueAtTime(Math.max(1,endHz),start+duration);gain.gain.setValueAtTime(.001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.008);gain.gain.exponentialRampToValueAtTime(.001,start+duration);oscillator.connect(gain);gain.connect(soundBus);oscillator.start(start);oscillator.stop(start+duration+.01);}
function playNoise(duration,cutoff,volume){const ctx=getAudioContext();if(!ctx||soundVolume<=0)return;const buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*duration),ctx.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*(1-i/samples.length);const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain(),start=ctx.currentTime;source.buffer=buffer;filter.type='lowpass';filter.frequency.value=cutoff;gain.gain.setValueAtTime(volume,start);gain.gain.exponentialRampToValueAtTime(.001,start+duration);source.connect(filter);filter.connect(gain);gain.connect(soundBus);source.start(start);}
