  const slideButton=document.createElement('button');slideButton.id='slideBtn';slideButton.className='touchButton';slideButton.textContent='SLIDE';slideButton.addEventListener('pointerdown',event=>{event.preventDefault();startSlide();});$('mobileControls').append(slideButton);window.addEventListener('keydown',event=>{if(state.playing&&!state.paused&&event.code===controlBindings.slide){event.preventDefault();startSlide();}});
  const matchmakingButton=document.createElement('button');matchmakingButton.id='matchmakingBtn';matchmakingButton.className='primaryBtn';matchmakingButton.textContent='FIND 1V1 MATCH';document.querySelector('.menuButtons').append(matchmakingButton);
  const quickPlayButton=document.createElement('button');quickPlayButton.id='quickPlayBtn';quickPlayButton.className='primaryBtn';quickPlayButton.textContent='QUICK PLAY · 20 PLAYERS';document.querySelector('.menuButtons').append(quickPlayButton);
  const menuSettings=document.createElement('button');menuSettings.id='menuSettingsBtn';menuSettings.className='secondaryBtn';menuSettings.textContent='SETTINGS';document.querySelector('.menuButtons').append(menuSettings);
  const pauseSettings=document.createElement('button');pauseSettings.id='pauseSettingsBtn';pauseSettings.className='secondaryBtn';pauseSettings.textContent='SETTINGS';document.querySelector('.pauseActions').append(pauseSettings);
  const panel=document.createElement('div');panel.id='settingsPanel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','settingsTitle');panel.innerHTML='<div class="settingsCard"><button id="settingsClose" class="settingsClose" aria-label="Close settings">×</button><div class="eyebrow">FIELD OPTIONS</div><h2 id="settingsTitle">SETTINGS</h2><label class="sensitivitySetting" for="sensitivityInput"><span>LOOK SENSITIVITY</span><output id="sensitivityValue"></output><input id="sensitivityInput" type="range" min="0.2" max="3" step="0.1"></label><label class="sensitivitySetting" for="sfxVolumeInput"><span>SOUND EFFECTS</span><output id="sfxVolumeValue"></output><input id="sfxVolumeInput" type="range" min="0" max="1" step="0.05"></label><h3>KEY BINDINGS</h3><div id="bindingList"></div><button id="resetBindings" class="secondaryBtn">RESET CONTROLS</button></div>';document.body.append(panel);
  const close=()=>{panel.classList.remove('open');bindingCapture=null;};const open=()=>{panel.classList.add('open');};menuSettings.addEventListener('click',open);pauseSettings.addEventListener('click',open);$('settingsClose').addEventListener('click',close);panel.addEventListener('pointerdown',e=>{if(e.target===panel)close();});
  const labels={forward:'Move forward',backward:'Move backward',left:'Move left',right:'Move right',jump:'Jump',reload:'Reload',nextWeapon:'Next weapon',sprint:'Sprint',interact:'Open chest',slide:'Slide'};
  const keyName=code=>({Space:'SPACE',ShiftLeft:'LEFT SHIFT',ShiftRight:'RIGHT SHIFT',ControlLeft:'LEFT CTRL',AltLeft:'LEFT ALT'}[code]||code.replace(/^Key/,'').replace(/^Digit/,'')||code);
  const renderBindings=()=>{const list=$('bindingList');list.replaceChildren();for(const [action,label] of Object.entries(labels)){const row=document.createElement('div');row.className='bindingRow';const name=document.createElement('span');name.textContent=label;const button=document.createElement('button');button.type='button';button.className='bindingKey';button.textContent=keyName(controlBindings[action]);button.addEventListener('click',()=>{bindingCapture=action;button.textContent='PRESS A KEY';});row.append(name,button);list.append(row);}};
  const sensitivityInput=$('sensitivityInput');sensitivityInput.value=String(lookSensitivity);$('sensitivityValue').textContent=`${lookSensitivity.toFixed(1)}×`;sensitivityInput.addEventListener('input',()=>{lookSensitivity=Number(sensitivityInput.value);$('sensitivityValue').textContent=`${lookSensitivity.toFixed(1)}×`;localStorage.setItem('fl_look_sensitivity',String(lookSensitivity));});
  const volumeInput=$('sfxVolumeInput');volumeInput.value=String(soundVolume);$('sfxVolumeValue').textContent=`${Math.round(soundVolume*100)}%`;volumeInput.addEventListener('input',()=>{soundVolume=Number(volumeInput.value);$('sfxVolumeValue').textContent=`${Math.round(soundVolume*100)}%`;localStorage.setItem('fl_sfx_volume',String(soundVolume));if(soundBus&&audioContext)soundBus.gain.setTargetAtTime(soundVolume,audioContext.currentTime,.02);});
  $('resetBindings').addEventListener('click',()=>{Object.assign(controlBindings,defaultBindings);localStorage.removeItem('fl_controls');bindingCapture=null;renderBindings();});renderBindings();
  $('trainingBtn').addEventListener('click',()=>playEffect('deploy'));$('onlineBtn').addEventListener('click',()=>playEffect('deploy'));for(const id of ['trainingBtn','onlineBtn','matchmakingBtn','quickPlayBtn'])$(id).addEventListener('click',()=>{state.sliding=false;state.slideUntil=0;state.slideCooldownUntil=0;});$('jumpBtn').addEventListener('pointerdown',()=>{if(state.playing&&!state.paused&&state.grounded)playEffect('jump');});window.addEventListener('keydown',e=>{if(state.playing&&!state.paused&&e.code===controlBindings.jump&&state.grounded)playEffect('jump');});
  window.addEventListener('keydown',e=>{if(bindingCapture){e.preventDefault();e.stopImmediatePropagation();controlBindings[bindingCapture]=e.code;localStorage.setItem('fl_controls',JSON.stringify(controlBindings));bindingCapture=null;renderBindings();return;}if(panel.classList.contains('open')&&e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}},true);
