function inputSetup(){installMenuOptions();window.addEventListener('keydown',e=>{state.keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!state.playing)return;if(e.code==='Escape'){if(document.pointerLockElement===canvas)document.exitPointerLock();togglePause(!state.paused);}if(state.paused)return;if(e.code===controlBindings.reload)reload();if(e.code===controlBindings.nextWeapon)cycleWeapon();if(/^Digit[1-2]$/.test(e.code)){const i=Number(e.code.slice(5))-1;selectWeapon(i);}if(e.code===controlBindings.interact)openNearestChest();if(e.code===controlBindings.jump&&state.grounded){state.velocityY=7.3;state.grounded=false;}});window.addEventListener('keyup',e=>{state.keys[e.code]=false;});canvas.addEventListener('click',()=>{if(state.playing&&!state.paused&&!touchMode&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.();});window.addEventListener('mousemove',e=>{if(state.playing&&!state.paused&&document.pointerLockElement===canvas){state.yaw-=e.movementX*.0021*lookSensitivity;state.pitch-=e.movementY*.0021*lookSensitivity;state.pitch=THREE.MathUtils.clamp(state.pitch,-1.48,1.48);}});canvas.addEventListener('mousedown',e=>{if(!state.playing||state.paused||touchMode)return;if(e.button===0)state.fireHeld=true;if(e.button===2)state.aiming=true;});window.addEventListener('mouseup',e=>{if(e.button===0)state.fireHeld=false;if(e.button===2)state.aiming=false;});window.addEventListener('contextmenu',e=>e.preventDefault());
  $('trainingBtn').addEventListener('click',()=>startGame(false));$('onlineBtn').addEventListener('click',()=>startGame(true));$('matchmakingBtn').addEventListener('click',()=>{matchmakingOnStart=true;startGame(true);});$('quickPlayBtn').addEventListener('click',()=>{quickPlayOnStart=true;startGame(true);});$('changeWeapon').addEventListener('click',cycleWeapon);$('resumeBtn').addEventListener('click',()=>togglePause(false));$('leaveBtn').addEventListener('click',leaveGame);
  document.querySelectorAll('.mapCard').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.mapCard').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.mapId=btn.dataset.map;}));
  bindStick('moveStick',true);bindStick('lookStick',false);bindTouchButton('fireBtn',()=>state.fireHeld=true,()=>state.fireHeld=false);bindTouchButton('aimBtn',()=>state.aiming=true,()=>state.aiming=false);$('reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload();});$('jumpBtn').addEventListener('pointerdown',e=>{e.preventDefault();if(state.grounded){state.velocityY=7.3;state.grounded=false;}});$('switchBtn').addEventListener('pointerdown',e=>{e.preventDefault();cycleWeapon();});
}
function bindStick(id,isMove){const el=$(id),knob=el.querySelector('.stickKnob');let pointer=null,start={x:0,y:0},previous={x:0,y:0};const reset=()=>{pointer=null;if(isMove)state.mobileMove={x:0,y:0};else state.mobileLookActive=false;knob.style.transform='translate(0px,0px)';};el.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;el.setPointerCapture(pointer);start={x:e.clientX,y:e.clientY};previous={x:e.clientX,y:e.clientY};if(!isMove)state.mobileLookActive=true;});el.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;e.preventDefault();let dx=e.clientX-start.x,dy=e.clientY-start.y,dist=Math.hypot(dx,dy),max=42;if(dist>max){dx=dx/dist*max;dy=dy/dist*max;}knob.style.transform=`translate(${dx}px,${dy}px)`;if(isMove){state.mobileMove={x:dx/max,y:dy/max};}else{const lookDX=e.clientX-previous.x,lookDY=e.clientY-previous.y;state.yaw-=lookDX*.005*lookSensitivity;state.pitch=THREE.MathUtils.clamp(state.pitch-lookDY*.005*lookSensitivity,-1.48,1.48);previous={x:e.clientX,y:e.clientY};}});el.addEventListener('pointerup',reset);el.addEventListener('pointercancel',reset);}
function bindTouchButton(id,down,up){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);down();});el.addEventListener('pointerup',e=>{e.preventDefault();up();});el.addEventListener('pointercancel',up);el.addEventListener('pointerleave',e=>{if(e.buttons===0)up();});}
function togglePause(open){if(!state.playing)return;state.paused=open;$('pauseMenu').classList.toggle('open',open);if(open&&document.pointerLockElement===canvas)document.exitPointerLock();else if(!open&&!touchMode)canvas.requestPointerLock?.();}
function leaveGame(){state.playing=false;state.paused=false;state.fireHeld=false;state.aiming=false;if(state.socket){if(state.matchmaking)sendNetwork({type:'cancel_matchmaking'});state.socket.close();state.socket=null;}state.matchmaking=false;state.connecting=false;state.online=false;document.exitPointerLock?.();$('pauseMenu').classList.remove('open');$('menu').classList.remove('hidden');$('mobileControls').classList.remove('active');document.querySelectorAll('.hud').forEach(el=>el.classList.remove('visible'));$('crosshair').classList.remove('show');clearGroup(actorsRoot);state.remote.clear();state.bots=[];}
function selectWeapon(i){state.weaponIndex=(i+2)%2;state.reloading=false;buildViewWeapon();updateHud();showToast(weaponForSlot().name);}
function cycleWeapon(){selectWeapon((state.weaponIndex+1)%2);}
function reload(){if(state.reloading||!state.playing||state.paused)return;const w=weaponForSlot(),a=ammoForWeapon(w);if(a.mag===magazineCapacity(w)||a.reserve<=0)return;state.reloading=true;playEffect('reload');$('reloadText').textContent='RELOADING';setTimeout(()=>{if(!state.playing)return;const need=magazineCapacity(w)-a.mag,take=Math.min(need,a.reserve);a.mag+=take;a.reserve-=take;state.reloading=false;playEffect('reloadDone');updateHud();},w.reload*1000);}
function shoot(){if(!state.playing||state.paused||state.dead||state.reloading)return;const w=weaponForSlot(),a=ammoForWeapon(w),now=performance.now();if(now-state.lastShot<w.rate)return;if(a.mag<=0){playEffect('empty');reload();return;}state.lastShot=now;a.mag--;playEffect('shot',w.id);const gripFactor=hasAttachment(w.id,'grip')?.65:1;weaponRecoil=Math.min(.22,weaponRecoil+(.08+(state.aiming?-.015:0))*gripFactor);updateHud();
  camera.position.set(local.x,local.y+(state.sliding?1.05:1.64)+cameraBob,local.z);camera.rotation.order='YXZ';camera.rotation.y=state.yaw;camera.rotation.x=state.pitch;camera.rotation.z=0;
  const origin=camera.position.clone(),direction=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion).normalize();let hitPoint=origin.clone().addScaledVector(direction,w.range),hitActor=null,hitMesh=null;
  raycaster.set(origin,direction);raycaster.far=w.range;const intersections=raycaster.intersectObjects([worldRoot,actorsRoot],true);if(intersections.length){const nearest=intersections[0];hitPoint=nearest.point.clone();let o=nearest.object;while(o&&o!==actorsRoot&&!o.userData.actorType)o=o.parent;if(o?.userData.actorType){hitActor=o;hitMesh=nearest.object;}}
  makeTracer(origin,hitPoint,w.id==='sniper'?0xffd9a0:0xd7f36a);
  if(hitActor){const headshot=hitMesh?.userData.hitRegion==='head';if(hitActor.userData.actorType==='bot'&&!state.online){damageBot(hitActor,w,headshot);$('crosshair').classList.add('hit');setTimeout(()=>$('crosshair').classList.remove('hit'),90);}else if(hitActor.userData.actorType==='player'&&state.online){sendNetwork({type:'fire',targetId:hitActor.userData.playerId,origin:{x:origin.x,y:origin.y,z:origin.z},direction:{x:direction.x,y:direction.y,z:direction.z},weapon:w.id});}}
  else if(state.online)sendNetwork({type:'fire',targetId:null,origin:{x:origin.x,y:origin.y,z:origin.z},direction:{x:direction.x,y:direction.y,z:direction.z},weapon:w.id});
  if(w.id==='sniper'||w.id==='dmr')showToast(w.id==='sniper'?'BOLT ACTION':'MARKSMAN');
}
function damageBot(root,w,headshot=false){playEffect('impact');let dmg=w.damage*(headshot?2:1);if(w.id==='shotgun')dmg*=1.3;root.userData.hp-=dmg;const bot=state.bots.find(b=>b.root===root);if(bot)bot.hp=root.userData.hp;if(root.userData.hp<=0){if(bot){bot.alive=false;actorsRoot.remove(root);clearTimeout(bot.respawnTimer);bot.respawnTimer=setTimeout(()=>{if(!state.playing||state.online||!state.bots.includes(bot))return;const spawn=pickSpawn();root.position.set(spawn[0],0,spawn[1]);root.rotation.y=Math.random()*Math.PI*2;root.userData.hp=100;root.userData.nextFire=performance.now()+800;bot.x=spawn[0];bot.z=spawn[1];bot.hp=100;bot.alive=true;bot.respawnTimer=null;actorsRoot.add(root);},4500);}else actorsRoot.remove(root);state.kills++;playEffect('kill');gainXP(125);showToast(headshot?'HEADSHOT ELIMINATION +125 XP':'BOT ELIMINATED +125 XP');}else showToast(headshot?`HEADSHOT · ${Math.round(dmg)} DMG`:`HIT CONFIRMED · ${Math.round(dmg)} DMG`);}
function makeTracer(a,b,color){advanceChallenge('shots');const geom=new THREE.BufferGeometry().setFromPoints([a,b]);const line=new THREE.Line(geom,new THREE.LineBasicMaterial({color,transparent:true,opacity:.82}));effectsRoot.add(line);state.effects.push({obj:line,time:.075});}
function gainXP(n){advanceChallenge('eliminations');state.xp+=n;const next=1+Math.floor(state.xp/500);if(next>state.level){state.level=next;showToast(`RANK UP · LEVEL ${state.level}`);buildViewWeapon();refreshClassEditorLocks();}localStorage.setItem('fl_xp',state.xp);localStorage.setItem('fl_kills',state.kills);updateHud();renderProgressionPanel();}
function updateHud(){const w=weaponForSlot(),a=ammoForWeapon(w);$('weaponName').textContent=w.name;$('weaponType').textContent=`${state.weaponIndex+1} / 2 · ${w.type}`;$('mag').textContent=a.mag;$('reserve').textContent=a.reserve;$('reloadText').textContent=state.reloading?'RELOADING':'';$('healthText').textContent=`${Math.max(0,Math.ceil(state.health))} / 100`;$('healthFill').style.width=`${THREE.MathUtils.clamp(state.health,0,100)}%`;$('armorText').textContent=`${Math.max(0,Math.ceil(state.armor))} / 50`;$('armorFill').style.width=`${THREE.MathUtils.clamp(state.armor/50*100,0,100)}%`;$('killsVal').textContent=state.kills;$('rankLine').textContent=`RANK ${String(state.level).padStart(2,'0')} · ${state.level<3?'RECRUIT':state.level<6?'OPERATOR':'VETERAN'}`;$('xpSmall').textContent=`${state.xp.toLocaleString()} XP EARNED`;$('levelName').textContent=`RANK ${String(state.level).padStart(2,'0')}`;$('xpLabel').textContent=`${state.xp%500} / 500 XP`;$('xpFill').style.width=`${state.xp%500/5}%`;}
function showToast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1550);}

function resolvePlayerOverlaps(){const radius=.38;for(let pass=0;pass<3;pass++)for(const obstacle of state.obstacles){if(local.y+1.8<obstacle.minY||local.y>obstacle.maxY+.05)continue;const overlapX=obstacle.hx+radius-Math.abs(local.x-obstacle.x),overlapZ=obstacle.hz+radius-Math.abs(local.z-obstacle.z);if(overlapX>0&&overlapZ>0){if(overlapX<overlapZ)local.x=obstacle.x+(local.x>=obstacle.x?1:-1)*(obstacle.hx+radius+.02);else local.z=obstacle.z+(local.z>=obstacle.z?1:-1)*(obstacle.hz+radius+.02);}}}
function startSlide(){const now=performance.now();if(!state.playing||state.paused||state.dead||!state.grounded||now<state.slideCooldownUntil)return;let mx=(state.keys[controlBindings.right]?1:0)-(state.keys[controlBindings.left]?1:0)+state.mobileMove.x,mz=(state.keys[controlBindings.backward]?1:0)-(state.keys[controlBindings.forward]?1:0)+state.mobileMove.y;const magnitude=Math.hypot(mx,mz);if(magnitude<.15)return;if(magnitude>1){mx/=magnitude;mz/=magnitude;}const forwardX=-Math.sin(state.yaw),forwardZ=-Math.cos(state.yaw),rightX=Math.cos(state.yaw),rightZ=-Math.sin(state.yaw),vx=rightX*mx+forwardX*(-mz),vz=rightZ*mx+forwardZ*(-mz),length=Math.hypot(vx,vz)||1;state.slideDirection={x:vx/length,z:vz/length};state.sliding=true;state.slideUntil=now+680;state.slideCooldownUntil=now+1450;playEffect('jump');showToast('SLIDE');}
function updateMovement(dt){if(state.sliding&&performance.now()>=state.slideUntil)state.sliding=false;const speed=state.sliding?11.5:(state.keys[controlBindings.sprint]?10.2:movementSpeed);let mx=(state.keys[controlBindings.right]?1:0)-(state.keys[controlBindings.left]?1:0),mz=(state.keys[controlBindings.backward]?1:0)-(state.keys[controlBindings.forward]?1:0);mx+=state.mobileMove.x;mz+=state.mobileMove.y;const mag=Math.hypot(mx,mz);if(mag>1){mx/=mag;mz/=mag;}const forwardX=-Math.sin(state.yaw),forwardZ=-Math.cos(state.yaw),rightX=Math.cos(state.yaw),rightZ=-Math.sin(state.yaw);let vx=(rightX*mx+forwardX*(-mz))*speed,vz=(rightZ*mx+forwardZ*(-mz))*speed;if(state.sliding){vx=state.slideDirection.x*11.5;vz=state.slideDirection.z*11.5;}
  const radius=.38;resolvePlayerOverlaps();const oldX=local.x,oldZ=local.z;local.x+=vx*dt;
  const mapBounds=maps[state.mapId].bounds||30;if(Math.abs(local.x)>mapBounds-radius)local.x=oldX;
  for(const o of state.obstacles){if(local.y+1.8<o.minY||local.y>o.maxY+.05)continue;if(Math.abs(local.x-o.x)<o.hx+radius&&Math.abs(oldZ-o.z)<o.hz+radius){local.x=oldX;break;}}
  local.z+=vz*dt;if(Math.abs(local.z)>mapBounds-radius)local.z=oldZ;
  for(const o of state.obstacles){if(local.y+1.8<o.minY||local.y>o.maxY+.05)continue;if(Math.abs(local.x-o.x)<o.hx+radius&&Math.abs(local.z-o.z)<o.hz+radius){local.z=oldZ;break;}}
  state.velocityY-=gravity*dt;local.y+=state.velocityY*dt;if(local.y<=0){local.y=0;state.velocityY=0;state.grounded=true;}cameraBob=THREE.MathUtils.lerp(cameraBob,mag>.1&&state.grounded?Math.sin(walkTime*2.1)*.035:0,.15);camera.position.set(local.x,local.y+(state.sliding?1.05:1.64)+cameraBob,local.z);camera.rotation.order='YXZ';camera.rotation.y=state.yaw;camera.rotation.x=state.pitch;camera.rotation.z=0;const hasOptic=hasAttachment(weaponForSlot().id,'optic'),aimFov=[48,42,42,45,32,18][weaponData.findIndex(item=>item.id===weaponForSlot().id)],targetFov=state.aiming?(hasOptic?aimFov:58):78;const oldFov=camera.fov;camera.fov=THREE.MathUtils.lerp(camera.fov,targetFov,.22);if(Math.abs(camera.fov-oldFov)>.02)camera.updateProjectionMatrix();
}
function updateBots(dt){if(state.online)return;const now=performance.now();for(const b of [...state.bots]){const r=b.root;if(!r.parent)continue;const dx=local.x-r.position.x,dz=local.z-r.position.z,d=Math.hypot(dx,dz);if(d>4){const sp=1.25;r.position.x+=dx/d*sp*dt;r.position.z+=dz/d*sp*dt;}r.rotation.y=Math.atan2(dx,dz);animateCharacter(r,now/1000,d>4);if(d<13&&now>r.userData.nextFire){r.userData.nextFire=now+1000+Math.random()*600;if(Math.random()<.58){let damage=5+Math.random()*5;if(state.armor>0){const absorb=Math.min(state.armor,damage*.65);state.armor-=absorb;damage-=absorb;}state.health=Math.max(0,state.health-damage);state.damageFlash=.35;if(state.health<=0){state.dead=true;setTimeout(()=>{if(state.playing&&!state.online&&state.dead){state.dead=false;state.health=100;state.armor=50;const p=pickSpawn();local.x=p[0];local.z=p[1];showToast('RESPAWNED');updateHud();}},2600);}updateHud();}}}}
function onResize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,touchMode?1.25:1.7));}
function tick(){const dt=Math.min(clock.getDelta(),.05);if(state.playing&&!state.paused){if(!state.dead)updateMovement(dt);if(state.fireHeld)shoot();if(!state.dead)updateBots(dt);updateRemoteActors(dt);updateViewWeapon(dt);if(state.online&&!state.dead){const now=performance.now();if(now-state.lastStateSend>55){state.lastStateSend=now;sendNetwork({type:'state',x:local.x,y:local.y,z:local.z,yaw:state.yaw,pitch:state.pitch,skin:state.skinIndex,level:state.level,weapon:weaponForSlot().id});}}}else updateRemoteActors(dt);
  for(let i=state.effects.length-1;i>=0;i--){const e=state.effects[i];e.time-=dt;if(e.time<=0){effectsRoot.remove(e.obj);e.obj.geometry.dispose();e.obj.material.dispose();state.effects.splice(i,1);}}
  if(state.damageFlash>0){state.damageFlash=Math.max(0,state.damageFlash-dt);$('hitVignette').style.opacity=String(state.damageFlash);}scopeOverlay.classList.toggle('active',state.playing&&!state.paused&&!state.dead&&state.aiming&&hasAttachment(weaponForSlot().id,'optic'));updateLootPrompt();renderer.render(scene,camera);}

inputSetup();initThree();updateHud();
